const HTML="<!doctype html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#060b14\"><meta name=\"description\" content=\"Shards MCP — connect Claude, ChatGPT, Codex, Cursor and other AI clients to a governed connectivity gateway.\"><title>SHARDS / MCP — Universal Agent Connectivity</title><style>\n:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif;background:#070b14;color:#e6f5fa;color-scheme:dark;scroll-behavior:smooth}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(ellipse 65vw 32vw at 79% -12%,#1e525f85,transparent 75%),radial-gradient(ellipse 50vw 32vw at -12% 45%,#1e2e4d70,transparent 70%),#070b14}button,input,select{font:inherit}button{cursor:pointer}button:disabled{opacity:.5;cursor:not-allowed}a{color:inherit;text-decoration:none}a:hover{text-decoration:underline}.shell{max-width:1330px;margin:0 auto;padding:18px 24px}.header{display:flex;justify-content:space-between;align-items:center;gap:20px;border-bottom:1px solid #263a4b80;padding:16px 0;flex-wrap:wrap}.brand{letter-spacing:.19em;font-size:13px;font-weight:850;display:flex;align-items:center;gap:9px}.symbol{display:grid;place-items:center;width:34px;height:34px;border:1px solid #6cddd6;border-radius:10px;box-shadow:0 0 18px #54c8ce34;color:#9dfbec;font-size:20px}.brand span{color:#8de4dd}.actions{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.chip{padding:8px 11px;font:700 10px ui-monospace,monospace;letter-spacing:.11em;text-transform:uppercase;color:#a8f7df;background:#0b2d31;border:1px solid #285b65;border-radius:90px}.chip.warn{background:#392927;color:#e9bb9b;border-color:#8b5a47}.navlink{border:1px solid #374e61;padding:10px 14px;border-radius:9px;font-size:12px;color:#c6e3ef;min-height:42px;display:inline-flex;align-items:center}.navlink:hover{border-color:#75d1d7;text-decoration:none}.hero{position:relative;display:grid;grid-template-columns:1.1fr .8fr;gap:24px;align-items:center;min-height:490px;padding:64px 0 40px}.eyebrow{font:750 11px ui-monospace,monospace;letter-spacing:.24em;color:#80e3dd;text-transform:uppercase}.hero h1{font-size:clamp(47px,7.4vw,103px);letter-spacing:-.075em;line-height:.94;margin:18px 0 23px;font-weight:820}.hero h1 em{font-style:normal;background:linear-gradient(125deg,#e7fff9,#7cdbdd 52%,#86a2fc);background-clip:text;-webkit-background-clip:text;color:transparent}.hero p{color:#a8bbcd;font-size:15px;line-height:1.85;max-width:630px}.cta{display:inline-flex;align-items:center;gap:8px;min-height:47px;padding:12px 17px;border-radius:10px;border:0;background:#91eadf;color:#091724;font-size:12px;font-weight:850;text-transform:uppercase;letter-spacing:.06em;transition:transform .2s,filter .2s}.cta:hover{filter:brightness(1.15);transform:translateY(-2px);text-decoration:none}.cta.outline{background:#183343;color:#c8f7f4;border:1px solid #356975}.ctarow{display:flex;flex-wrap:wrap;gap:10px;margin-top:25px}.art{position:relative;height:355px;display:grid;place-items:center;pointer-events:none}.art svg{width:100%;max-width:450px;max-height:370px;filter:drop-shadow(0 0 25px #2ab0b040)}.orb-1{transform-origin:center;animation:rotatea 22s linear infinite}.orb-2{transform-origin:center;animation:rotateb 29s linear infinite}.orb-3{transform-origin:center;animation:rotatea 38s linear infinite}@keyframes rotatea{to{transform:rotate(360deg)}}@keyframes rotateb{to{transform:rotate(-360deg)}}.ringtext{position:absolute;bottom:2%;left:0;right:0;text-align:center;color:#7b98b1;letter-spacing:.3em;font:10px ui-monospace,monospace}.specs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:0 0 45px}.spec{border-top:1px solid #426275;padding:14px 10px;background:linear-gradient(#0d243250,#070d1800)}.spec b{display:block;font:700 12px ui-monospace,monospace;color:#e5faf5}.spec span{display:block;color:#7998ac;font:10px ui-monospace,monospace;margin-top:6px;line-height:1.6}.section{padding:45px 0 18px;scroll-margin-top:30px}.head{display:flex;justify-content:space-between;align-items:end;gap:25px;flex-wrap:wrap;margin-bottom:21px}.head h2{font-size:clamp(26px,4vw,46px);letter-spacing:-.055em;line-height:1.1;margin:12px 0 0}.head p{max-width:450px;color:#95afc2;font-size:12px;line-height:1.8}.counter{color:#71b9bf;font:10px ui-monospace,monospace;letter-spacing:.2em}.panel{background:linear-gradient(145deg,#102334e8,#0b1424eb);border:1px solid #30495f;border-radius:17px;padding:22px;box-shadow:inset 0 1px #ffffff0a,0 16px 38px #0002}.flow-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.clientnav{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px;margin-bottom:18px}.clienttab{border:1px solid #344c60;background:#0d2030;color:#9ebed1;padding:14px 7px;border-radius:10px;font-size:12px;font-weight:650;min-height:49px}.clienttab[aria-selected=true]{color:#a5f9e9;border-color:#6de9d3;background:#173c46;box-shadow:inset 0 0 16px #4bcdc216}.clienttab:hover{border-color:#60c0c2}.setup{display:grid;grid-template-columns:.85fr 1.15fr;gap:20px}.setup h3{margin:0 0 12px;font-size:22px;letter-spacing:-.04em}.setup p{color:#a4bdcc;font-size:13px;line-height:1.85}.steps{padding-left:18px;margin:12px 0;color:#adc8d8;font-size:12px;line-height:2}.steps li{padding-left:3px}.codebox{position:relative;border:1px solid #3f596f;background:#050f1c;border-radius:11px;padding:16px;min-height:115px}.codebox pre{font:12px/1.85 ui-monospace,Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere;color:#bbf3e6;margin:0;padding-right:0}.copy{border:1px solid #4c7480;background:#153a45;color:#c0f9f0;padding:9px 13px;border-radius:9px;font-size:11px;font-weight:750;min-height:41px}.copy:hover{background:#285b64}.status{padding:10px 13px;border:1px solid #2b666c;background:#0a2a31;color:#bdf3e4;border-radius:10px;font:11px/1.7 ui-monospace,monospace;min-height:41px;overflow-wrap:anywhere}.note{font-size:11px;line-height:1.7;color:#9ab0c4}.warning{border-left:3px solid #b89b6f;background:#35282675;color:#e0c7ad;padding:12px;border-radius:6px;font-size:11px;line-height:1.7;margin-top:13px}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.tool{border:1px solid #2c475c;border-radius:13px;padding:18px;background:#0c1f30aa;min-width:0}.tool h3{font-size:17px;letter-spacing:-.035em;margin:12px 0 6px}.tool p{font-size:12px;color:#9bb5c5;line-height:1.75}.index{font:11px ui-monospace,monospace;color:#87e0d6}.limits{display:flex;gap:7px;flex-wrap:wrap}.mini{border-radius:50px;border:1px solid #365462;padding:6px 9px;color:#8cabbf;font:9px ui-monospace,monospace}.mini.ok{color:#a1f4df;border-color:#417e75}.endpoint{display:flex;align-items:center;justify-content:space-between;gap:12px;border:1px solid #416579;padding:13px 16px;background:#092431;border-radius:11px;flex-wrap:wrap}.endpoint code{color:#c0fbf0;font:12px ui-monospace,monospace;overflow-wrap:anywhere}.onboarding{display:grid;grid-template-columns:1fr 1fr;gap:15px}.flow{display:flex;align-items:start;gap:14px}.num{display:grid;place-items:center;flex-shrink:0;width:32px;height:32px;border:1px solid #49868a;color:#95ecde;font:12px ui-monospace,monospace;border-radius:8px}.flow h3{margin:0 0 7px;font-size:15px}.flow p{margin:0;color:#95afc1;line-height:1.75;font-size:12px}.market{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.market a{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:13px;border-radius:9px;border:1px solid #2d4556;background:#0c1c2b;color:#b7d5e4;font-size:12px;min-height:47px}.market a:hover{border-color:#73bfbd;text-decoration:none}.muted{color:#8aa1b4}.manage{padding:23px;border:1px solid #435978;background:linear-gradient(140deg,#102b3a,#0f1729);border-radius:16px}.field{width:100%;border-radius:9px;border:1px solid #456072;background:#060f1e;color:#d4f4f4;padding:12px 13px;outline:none;font-size:13px;min-height:45px}.field:focus{border-color:#6cdbd7}.label{display:block;text-transform:uppercase;letter-spacing:.1em;font:10px ui-monospace,monospace;color:#97b4c7;margin-bottom:8px}.formgrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.console{display:none}.console.visible{display:block}.tokenout{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.8 ui-monospace,monospace;border:1px solid #437a77;background:#06292a;color:#c6ffef;padding:14px;border-radius:10px;margin:13px 0}.divider{border:0;border-top:1px solid #304659;margin:20px 0}.foot{margin-top:65px;padding:26px 0 35px;border-top:1px solid #33475d;color:#849ba8;font-size:11px;display:flex;gap:14px;justify-content:space-between;flex-wrap:wrap}.foot a{color:#a1d8d6}.hidden{display:none!important}@media(max-width:900px){.hero{grid-template-columns:1fr;gap:5px;padding:44px 0 15px}.art{height:240px}.specs{grid-template-columns:repeat(2,1fr)}.cards{grid-template-columns:repeat(2,1fr)}.setup{grid-template-columns:1fr}.clientnav{grid-template-columns:repeat(4,minmax(0,1fr))}.onboarding{grid-template-columns:1fr}}@media(max-width:600px){.shell{padding:12px 15px}.header{padding:10px 0}.hero{padding:43px 0 5px}.hero h1{font-size:clamp(43px,12vw,68px)}.hero p{font-size:13px;line-height:1.75}.art{height:175px;margin-top:5px}.art svg{max-height:195px}.section{padding-top:43px}.panel{padding:17px}.clientnav{grid-template-columns:repeat(2,minmax(0,1fr))}.cards,.onboarding,.formgrid{grid-template-columns:1fr}.market{grid-template-columns:1fr 1fr}.specs{grid-template-columns:1fr 1fr}.cta{font-size:11px;padding:11px 13px;flex:1;justify-content:center}.head h2{font-size:32px}.head p{margin:0}.navlink{font-size:11px}.brand{font-size:11px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;scroll-behavior:auto!important;transition:none!important}}\n</style></head><body><div class=\"shell\"><header class=\"header\"><a href=\"/\" class=\"brand\"><span class=\"symbol\">◇</span> SHARDS <span>/ MCP</span></a><div class=\"actions\"><span id=\"liveStatus\" class=\"chip\">CHECKING LIVE ENDPOINT</span><a class=\"navlink\" href=\"#connect\">Connect client</a><a class=\"navlink\" href=\"/manage\">Operator sign-in ↗</a></div></header><main>\n<section class=\"hero\"><div><span class=\"eyebrow\">Universal agent infrastructure / deployed gateway</span><h1>ONE GATEWAY.<br><em>EVERY AGENT.</em></h1><p>Connect AI clients to real, governed messaging and task coordination. Discover tools over MCP Streamable HTTP. Assign independently scoped identities and maintain a durable audit trail. Begin with read-only discovery, then enrol agents to unlock controlled collaboration.</p><div class=\"ctarow\"><a class=\"cta\" href=\"#connect\">CONNECT YOUR AI ↗</a><a class=\"cta outline\" href=\"#onboard\">AGENT GET STARTED</a><a class=\"cta outline\" href=\"https://github.com/Shards-foundation/Shards-MCP\" target=\"_blank\" rel=\"noopener noreferrer\">VIEW OPEN SOURCE ↗</a></div></div><div class=\"art\" aria-hidden=\"true\"><svg viewBox=\"0 0 500 500\" fill=\"none\"><defs><radialGradient id=\"g\"><stop stop-color=\"#b6fff3\"/><stop offset=\".42\" stop-color=\"#56afcc\"/><stop offset=\"1\" stop-color=\"#124f76\" stop-opacity=\"0\"/></radialGradient><linearGradient id=\"a\"><stop stop-color=\"#a9fff0\"/><stop offset=\".55\" stop-color=\"#55d5d0\"/><stop offset=\"1\" stop-color=\"#4568b6\"/></linearGradient></defs><circle cx=\"250\" cy=\"250\" r=\"110\" fill=\"url(#g)\" opacity=\".5\"/><g stroke=\"#336174\" opacity=\".36\"><circle cx=\"250\" cy=\"250\" r=\"210\"/><circle cx=\"250\" cy=\"250\" r=\"155\"/><path d=\"M40 250h420M250 40v420\" stroke-dasharray=\"3 8\"/></g><g class=\"orb-1\" stroke=\"url(#a)\" stroke-width=\"1.7\"><ellipse cx=\"250\" cy=\"250\" rx=\"203\" ry=\"75\" transform=\"rotate(31 250 250)\"/><ellipse cx=\"250\" cy=\"250\" rx=\"203\" ry=\"75\" transform=\"rotate(120 250 250)\"/></g><g class=\"orb-2\" stroke=\"#d7a16f\" stroke-width=\"2\"><ellipse cx=\"250\" cy=\"250\" rx=\"170\" ry=\"102\" transform=\"rotate(-39 250 250)\"/><ellipse cx=\"250\" cy=\"250\" rx=\"170\" ry=\"102\" transform=\"rotate(77 250 250)\"/></g><g class=\"orb-3\" stroke=\"#92e8e5\" stroke-width=\"1\"><ellipse cx=\"250\" cy=\"250\" rx=\"180\" ry=\"162\"/></g><circle cx=\"250\" cy=\"250\" r=\"35\" fill=\"url(#g)\" stroke=\"#83fff4\" stroke-width=\"2\"/><circle cx=\"250\" cy=\"250\" r=\"8\" fill=\"#c4fcf5\"/><g fill=\"#d3a779\"><circle cx=\"101\" cy=\"157\" r=\"5\"/><circle cx=\"389\" cy=\"296\" r=\"5\"/></g></svg><div class=\"ringtext\">IDENTITY → PERMISSION → ACTION → EVIDENCE</div></div></section>\n<div class=\"specs\"><div class=\"spec\"><b>HTTPS / MCP</b><span>Streamable HTTP transport</span></div><div class=\"spec\"><b>AUTHENTICATED</b><span>Scoped bearer credentials</span></div><div class=\"spec\"><b>DURABLE</b><span>EU Cloudflare D1 storage</span></div><div class=\"spec\"><b>FAIL CLOSED</b><span>No arbitrary tool execution</span></div></div>\n<section id=\"connect\" class=\"section\"><div class=\"head\"><div><span class=\"counter\">01 / CLIENT CONNECTIONS</span><h2>Connect in your environment.</h2></div><p>Choose your AI host. Every configuration uses the actual live endpoint; provider-specific installation is explicit. Anonymous connections expose only public discovery tools.</p></div><div class=\"panel\"><div class=\"endpoint\"><code id=\"endpoint\">https://mcp.shardsinc.co.uk/mcp</code><button class=\"copy\" data-copy=\"endpoint\">COPY ENDPOINT</button></div><div class=\"clientnav\" style=\"margin-top:20px\" role=\"tablist\" aria-label=\"Select MCP client\"><button class=\"clienttab\" role=\"tab\" aria-selected=\"true\" data-client=\"claude-desktop\">Claude Desktop</button><button class=\"clienttab\" role=\"tab\" aria-selected=\"false\" data-client=\"claude-code\">Claude Code</button><button class=\"clienttab\" role=\"tab\" aria-selected=\"false\" data-client=\"chatgpt\">ChatGPT</button><button class=\"clienttab\" role=\"tab\" aria-selected=\"false\" data-client=\"codex-app\">Codex app</button><button class=\"clienttab\" role=\"tab\" aria-selected=\"false\" data-client=\"codex-cli\">Codex CLI</button><button class=\"clienttab\" role=\"tab\" aria-selected=\"false\" data-client=\"cursor-app\">Cursor app</button><button class=\"clienttab\" role=\"tab\" aria-selected=\"false\" data-client=\"cursor-cli\">Cursor CLI</button><button class=\"clienttab\" role=\"tab\" aria-selected=\"false\" data-client=\"generic\">Universal</button></div><div class=\"setup\"><div><h3 id=\"clientTitle\">Claude Desktop</h3><p id=\"clientDescription\">Add a custom Web connector, provide the endpoint and review discovered tools.</p><ol id=\"clientSteps\" class=\"steps\"></ol><div class=\"ctarow\"><a class=\"cta\" id=\"clientOpen\" href=\"https://claude.ai/settings/connectors\" target=\"_blank\" rel=\"noopener noreferrer\">OPEN CLIENT SETUP ↗</a><button class=\"copy\" id=\"clientCopy\">COPY CONFIGURATION</button></div></div><div><span class=\"label\">Executable command / configuration</span><div class=\"codebox\"><pre id=\"clientCode\"></pre></div><div class=\"warning\" id=\"clientCaveat\">Remote AI hosts must accept the custom MCP server. Read-only public tools need no login; controlled agent operations require an individual scoped key.</div></div></div></div></section>\n<section id=\"onboard\" class=\"section\"><div class=\"head\"><div><span class=\"counter\">02 / AGENT ONBOARDING</span><h2>From first connection to governed action.</h2></div><p>No root token in model prompts. Each agent receives a separate, revocable, time-limited credential with explicit capabilities.</p></div><div class=\"onboarding\"><div class=\"panel flow\"><span class=\"num\">01</span><div><h3>Discover the gateway</h3><p>Connect your client to <code>https://mcp.shardsinc.co.uk/mcp</code>. Test <code>shards_gateway_status</code> or <code>shards_systems_catalog</code> without handing over any credential.</p></div></div><div class=\"panel flow\"><span class=\"num\">02</span><div><h3>Authenticate as the operator</h3><p>Enter the protected operator console using Cloudflare Access. Registration is not open to anonymous visitors. Each agent is separately enrolled.</p></div></div><div class=\"panel flow\"><span class=\"num\">03</span><div><h3>Issue a scoped agent key</h3><p>Choose an identity and client, generate a key, and store it in a local secret manager or environment variable. The server only retains a SHA-256 credential digest.</p></div></div><div class=\"panel flow\"><span class=\"num\">04</span><div><h3>Exchange messages and tasks</h3><p>Use <code>shards_message_send</code>, <code>shards_message_inbox</code>, <code>shards_task_create</code>, and <code>shards_task_claim</code>. Agents can operate only within their assigned tenant and permissions.</p></div></div></div><div class=\"ctarow\"><a class=\"cta\" href=\"/manage\">SIGN IN TO ENROL AGENTS ↗</a><a class=\"cta outline\" href=\"https://github.com/Shards-foundation/Shards-MCP\" target=\"_blank\" rel=\"noopener noreferrer\">RUN THE FULL PYTHON GATEWAY ↗</a></div></section>\n<section id=\"tools\" class=\"section\"><div class=\"head\"><div><span class=\"counter\">03 / LIVE CAPABILITIES</span><h2>Tools backed by execution.</h2></div><p>Real protocol operations, never simulated successful calls. Controlled operations are only enabled for authenticated, scoped agents; public discovery is intentionally read-only.</p></div><div id=\"toolsGrid\" class=\"cards\"></div></section>\n<section class=\"section\" id=\"operator\"><div class=\"head\"><div><span class=\"counter\">04 / OPERATOR CONSOLE</span><h2>Identity is infrastructure.</h2></div><p>Cloudflare Access protects the console. Agent registration and revocation require a signed, validated identity assertion.</p></div><div class=\"manage\"><div id=\"operatorPublic\"><p class=\"note\">Use Cloudflare Access to enter the private operator console. Anonymous access cannot create credentials or change tasks.</p><a href=\"/manage\" class=\"cta\">OPEN PROTECTED CONSOLE ↗</a></div><div id=\"operatorConsole\" class=\"console\"><p class=\"status\" id=\"operatorStatus\">Checking signed operator session…</p><div class=\"formgrid\" style=\"margin-top:19px\"><div><label class=\"label\" for=\"agentName\">Agent name / machine principal</label><input class=\"field\" id=\"agentName\" maxlength=\"50\" placeholder=\"claude-code-builder\"></div><div><label class=\"label\" for=\"agentClient\">Client / runtime</label><select id=\"agentClient\" class=\"field\"><option>Claude Code</option><option>Claude Desktop</option><option>Codex CLI</option><option>Codex app</option><option>Cursor</option><option>Hermes / independent</option><option>Other MCP client</option></select></div></div><p class=\"note\">Issued agents receive explicit message and task scopes. Credentials expire in 30 days and can be revoked. Each client should have its own identity.</p><div style=\"margin:14px 0 17px\"><span class=\"label\">Grant only required operations</span><div id=\"scopeSelection\" class=\"limits\" aria-label=\"Agent permission scopes\" style=\"gap:8px\"></div></div><button id=\"issueToken\" class=\"cta\">GENERATE AGENT KEY</button><div id=\"issuedToken\" class=\"tokenout hidden\"></div><div class=\"ctarow\"><button id=\"copyIssuedToken\" class=\"copy hidden\">COPY KEY ONCE</button></div><hr class=\"divider\"><span class=\"label\">Enrolled agent identities</span><div id=\"agentList\" class=\"note\">Loading…</div></div></div></section>\n<section id=\"marketplaces\" class=\"section\"><div class=\"head\"><div><span class=\"counter\">05 / DISCOVERY AND DISTRIBUTION</span><h2>Marketplace readiness.</h2></div><p>These are discovery and submission destinations, not claims of approval or listing. Every marketplace has independent review, publisher and commercial conditions.</p></div><div class=\"market\"><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://mcpmarket.com/\">MCP Market ↗</a><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://mcp-marketplace.io/\">MCP Marketplace ↗</a><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://openai.com/business/marketplace/\">OpenAI Marketplace ↗</a><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://claude.com/marketplace\">Claude Marketplace ↗</a><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://marketplace.microsoft.com/en-us/\">Microsoft Marketplace ↗</a><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://workspace.google.com/marketplace/category/popular-apps\">Google Workspace ↗</a><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://github.com/marketplace\">GitHub Marketplace ↗</a><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://marketplace.oracle.com/\">Oracle Marketplace ↗</a><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://discadia.com/\">Discadia ↗</a><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://top.gg/\">Top.gg ↗</a></div><div class=\"warning\">Shards-MCP is not yet listed or approved by these directories. Discord bot directories, enterprise software marketplaces and MCP registries have different integration and distribution models.</div></section>\n</main><footer class=\"foot\"><span>SHARDS FOUNDATION / MCP CONNECTIVITY · OPERATOR-GOVERNED · EXPERIMENTAL EDGE SERVICE</span><span><a href=\"https://github.com/Shards-foundation/Shards-MCP\">Source / security</a> · <a href=\"https://shardsinc.co.uk\">Shards Inc</a> · <a href=\"/api/status\">Live status</a></span></footer></div><script src=\"/app.js\" defer></script></body></html>";
const CLIENT="'use strict';(()=>{const $=id=>document.getElementById(id);const endpoint='https://mcp.shardsinc.co.uk/mcp';const clients={\n'claude-desktop':{name:'Claude Desktop',desc:'Claude Desktop supports a remote custom Web connector. Add it through Customize > Connectors.',steps:['Open Claude Desktop and go to Customize → Connectors.','Choose Add → Custom → Web.','Paste the HTTPS MCP endpoint, choose No sign-in for public tools, then save.','For private agent operations, configure a Bearer Authorization request header using your own scoped key.'],code:endpoint,url:'https://claude.ai/settings/connectors',button:'OPEN CLAUDE CONNECTORS ↗',caveat:'Claude may require account/workspace permissions. A direct URL alone exposes only public read-only tools.'},\n'claude-code':{name:'Claude Code',desc:'Install the HTTP endpoint in your local Claude Code environment.',steps:['Open Terminal where Claude Code is installed.','Run the command shown and then run claude mcp list.','Run /mcp inside Claude Code and inspect available tools.','For agent messaging use a scoped credential and header configuration; never paste an administrator secret.'],code:'claude mcp add --transport http shards-mcp '+endpoint+'\\nclaude mcp list',url:'https://code.claude.com/docs/en/mcp',button:'OPEN CLAUDE CODE DOCS ↗',caveat:'The exact credential-header setup depends on Claude Code version. Public discovery requires no key.'},\n'chatgpt':{name:'ChatGPT',desc:'Add a custom MCP server from ChatGPT Plugins on the web where your plan and workspace permissions support it.',steps:['Open ChatGPT on the web, then Plugins → + → Add custom MCP server.','Enter Shards MCP and the public endpoint.','Choose no authentication for read-only public tools, review the risk warning and scan tools.','Protected tools need a future OAuth integration; token-only operator enrolment is not ChatGPT OAuth.'],code:endpoint,url:'https://chatgpt.com/plugins',button:'OPEN CHATGPT PLUGINS ↗',caveat:'Full customer OAuth sign-in and write-tool onboarding in ChatGPT are NOT available yet. Only public read-only tools should be connected without auth.'},\n'codex-app':{name:'Codex app',desc:'Codex app and Codex CLI can share your MCP configuration.',steps:['Install Codex CLI on your machine if needed.','Run the command, or add the TOML shown in ~/.codex/config.toml.','Reopen Codex app and inspect tools.','Use individual agent credentials for private tools once supported in your setup.'],code:'codex mcp add shards-mcp --url '+endpoint+'\\n# Shared with Codex app\\ncodex mcp list',url:'https://developers.openai.com/codex/mcp',button:'OPEN CODEX DOCS ↗',caveat:'Codex app support is based on its shared MCP configuration; this button cannot install into a remote device.'},\n'codex-cli':{name:'Codex CLI',desc:'Register the remote endpoint directly with Codex CLI.',steps:['Run the add command in a local terminal.','Check the configured server using codex mcp list.','Use the read-only catalog tool to verify discovery.','Store private credentials securely outside shell history.'],code:'codex mcp add shards-mcp --url '+endpoint+'\\ncodex mcp list',url:'https://developers.openai.com/codex/mcp',button:'OPEN CODEX CLI DOCS ↗',caveat:'Public discovery is live. Authenticated tools require a per-agent key, not a shared root/admin token.'},\n'cursor-app':{name:'Cursor app',desc:'Use a real Cursor MCP deep link for one-click installation of the public read-only endpoint.',steps:['Click Add to Cursor to open the official Cursor MCP installation handler.','Review the server URL in Cursor before confirming.','Verify Shards MCP under Cursor → Customize → MCP.','For protected tools, configure an individual scoped key in your own secure environment.'],code:JSON.stringify({mcpServers:{'shards-mcp':{url:endpoint}}},null,2),url:'https://cursor.com/docs/mcp/install-links',button:'ADD TO CURSOR ↗',caveat:'The deeplink installs the public read-only MCP endpoint. It does not grant a secret or provision a customer identity.'},\n'cursor-cli':{name:'Cursor CLI',desc:'Cursor CLI reads the same MCP configuration used by Cursor editor.',steps:['Add the JSON in ~/.cursor/mcp.json or project .cursor/mcp.json.','Launch Cursor CLI and run agent mcp list.','Select the Shards MCP server and inspect its tools.','For protected collaboration, add a separate per-client token using supported configuration.'],code:JSON.stringify({mcpServers:{'shards-mcp':{url:endpoint}}},null,2)+'\\n\\n# Verify\\nagent mcp list',url:'https://cursor.com/docs/cli/mcp',button:'OPEN CURSOR CLI DOCS ↗',caveat:'Cursor CLI inherits configured editor MCP servers; no separate marketplace publication is required for manual use.'},\n'generic':{name:'Universal MCP',desc:'Connect any Streamable HTTP MCP-compatible client.',steps:['Set transport to Streamable HTTP.','Set server URL to the HTTPS endpoint.','Negotiate with initialize (legacy MCP) or server/discover for modern stateless MCP.','For protected tools send Authorization: Bearer with an operator-issued scoped agent token.'],code:'POST '+endpoint+'\\nContent-Type: application/json\\nAccept: application/json, text/event-stream\\n\\n{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"initialize\",\"params\":{\"protocolVersion\":\"2025-11-25\",\"capabilities\":{},\"clientInfo\":{\"name\":\"example\",\"version\":\"1.0\"}}}',url:'https://modelcontextprotocol.io/specification',button:'OPEN MCP SPEC ↗',caveat:'Not every client supports every MCP protocol revision or custom bearer headers. Test each host before assuming interoperability.'}\n};\nlet active='claude-desktop';const deeplink=()=>{const config={url:endpoint};const ascii=btoa(unescape(encodeURIComponent(JSON.stringify(config))));return 'cursor://anysphere.cursor-deeplink/mcp/install?name=shards-mcp&config='+encodeURIComponent(ascii)};\nconst selected=()=>clients[active];function drawClient(){const x=selected();$('clientTitle').textContent=x.name;$('clientDescription').textContent=x.desc;$('clientCode').textContent=x.code;$('clientCaveat').textContent=x.caveat;const list=$('clientSteps');list.replaceChildren();x.steps.forEach(step=>{const li=document.createElement('li');li.textContent=step;list.append(li)});const a=$('clientOpen');a.href=active==='cursor-app'?deeplink():x.url;a.textContent=x.button;a.target=active==='cursor-app'?'_self':'_blank';for(const b of document.querySelectorAll('[data-client]'))b.setAttribute('aria-selected',String(b.dataset.client===active))}\ndocument.querySelectorAll('[data-client]').forEach(el=>el.addEventListener('click',()=>{active=el.dataset.client;drawClient()}));drawClient();\nasync function copy(v){try{await navigator.clipboard.writeText(v);return true}catch{const t=document.createElement('textarea');t.value=v;t.style.position='fixed';t.style.opacity='0';document.body.append(t);t.select();let ok=false;try{ok=document.execCommand('copy')}finally{t.remove()}return ok}}\n$('clientCopy').addEventListener('click',async()=>{const b=$('clientCopy');b.textContent=await copy(selected().code)?'COPIED ✓':'SELECT AND COPY';setTimeout(()=>b.textContent='COPY CONFIGURATION',1600)});\ndocument.querySelector('[data-copy=endpoint]').addEventListener('click',async e=>{e.currentTarget.textContent=await copy(endpoint)?'COPIED ✓':'COPY FAILED';setTimeout(()=>e.currentTarget.textContent='COPY ENDPOINT',1800)});\nasync function status(){try{const r=await fetch('/api/status',{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);const x=await r.json();$('liveStatus').textContent=x.db==='connected'?'● MCP ONLINE · DATABASE LIVE':'MCP DEGRADED';$('liveStatus').classList.toggle('warn',x.db!=='connected');const node=$('toolsGrid');node.replaceChildren();for(const [i,t] of x.tools.entries()){const c=document.createElement('article');c.className='tool';const n=document.createElement('span');n.className='index';n.textContent=String(i+1).padStart(2,'0')+' / '+(t.public?'OPEN':'SCOPED');const title=document.createElement('h3');title.textContent=t.name;const p=document.createElement('p');p.textContent=t.description;const meta=document.createElement('span');meta.className='mini '+(t.public?'ok':'');meta.textContent=t.public?'No sign-in':'Individual agent token';c.append(n,title,p,meta);node.append(c)}}catch(err){$('liveStatus').textContent='SERVICE UNAVAILABLE';$('liveStatus').classList.add('warn');$('toolsGrid').textContent='Live service could not be verified: '+err.message}}\nstatus();\nconst managing=location.pathname.startsWith('/manage');if(managing){$('operatorPublic').classList.add('hidden');$('operatorConsole').classList.add('visible');}\nconst availableScopes=['agent:identity','agent:list','message:send','message:read','task:create','task:read','task:claim','task:complete'];const defaultScopes=new Set(['agent:identity','agent:list','message:send','message:read']);for(const scope of availableScopes){const l=document.createElement('label');l.style.cssText='display:inline-flex;gap:7px;align-items:center;border:1px solid #335b67;border-radius:8px;background:#0b2936;padding:10px 11px;font:11px ui-monospace,monospace;color:#b9e7df;min-height:44px';const c=document.createElement('input');c.type='checkbox';c.value=scope;c.checked=defaultScopes.has(scope);c.disabled=scope==='agent:identity';c.setAttribute('aria-label','Grant '+scope);l.append(c,document.createTextNode(scope));$('scopeSelection').append(l)}\nlet once='';\nasync function management(url,options){const r=await fetch(url,{cache:'no-store',...options});const body=await r.json().catch(()=>({error:'Invalid server response'}));if(!r.ok)throw Error(body.error||'HTTP '+r.status);return body}\nasync function loadAgents(){if(!managing)return;try{const data=await management('/manage/api/agents');$('operatorStatus').textContent='SIGNED OPERATOR SESSION VERIFIED · '+(data.agents||[]).length+' agents';$('agentList').replaceChildren();if(!data.agents.length)$('agentList').textContent='No agents enrolled yet.';for(const a of data.agents){const d=document.createElement('div');d.style.cssText='display:flex;justify-content:space-between;align-items:center;gap:8px;padding:12px 0;border-bottom:1px solid #284254';const label=document.createElement('span');label.textContent=a.name+' · '+a.client+' · '+(a.disabled_at?'REVOKED':'ACTIVE');const rev=document.createElement('button');rev.className='copy';rev.textContent='REVOKE';rev.disabled=!!a.disabled_at;rev.addEventListener('click',async()=>{if(!confirm('Revoke this agent and its associated tokens?'))return;try{await management('/manage/api/revoke',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({agent_id:a.id})});await loadAgents()}catch(err){$('operatorStatus').textContent=err.message}});d.append(label,rev);$('agentList').append(d)}}catch(err){$('operatorStatus').textContent='Operator session unavailable: '+err.message;}}\n$('issueToken').addEventListener('click',async()=>{const name=$('agentName').value.trim();if(!/^[a-zA-Z0-9][a-zA-Z0-9_-]{2,49}$/.test(name)){$('operatorStatus').textContent='Agent name: 3–50 alphanumeric / underscore / dash characters.';return}const button=$('issueToken');button.disabled=true;try{const v=await management('/manage/api/agents',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name,client:$('agentClient').value,scopes:[...$('scopeSelection').querySelectorAll('input:checked')].map(x=>x.value)})});once=v.token;$('issuedToken').textContent='SCOPED TOKEN — COPY NOW. NOT STORED IN PLAINTEXT BY THE SERVER.\\n\\n'+v.token+'\\n\\nEXPIRES: '+v.expires_at;$('issuedToken').classList.remove('hidden');$('copyIssuedToken').classList.remove('hidden');$('operatorStatus').textContent='Agent created. Copy the token to a secure secret manager before leaving this page.';await loadAgents()}catch(err){$('operatorStatus').textContent='Token issuance failed: '+err.message}finally{button.disabled=false}});\n$('copyIssuedToken').addEventListener('click',async()=>{if(!once)return;const b=$('copyIssuedToken');b.textContent=await copy(once)?'KEY COPIED ✓':'COPY FAILED';setTimeout(()=>b.textContent='COPY KEY ONCE',1800)});\nwindow.addEventListener('pagehide',()=>once='');\nif(managing)loadAgents();\n})();";
